package raft

import (
	"fmt"
	"testing"
	"time"
)

// TestAssurance_ConfigIndexBasis observes, on one running bootstrapped leader,
// the configuration index that the public API hands to a caller
// (GetConfiguration().Index(), and Stats()["latest_configuration_index"])
// next to the index the main thread holds for the latest configuration entry
// (r.configurations.latestIndex, served over configurationsCh).
//
// Initialization: MakeCluster(3) bootstraps a real three-node cluster, which
// writes a real configuration entry (index 1) and elects a leader; one client
// command is then committed so that commit/applied indexes are past the
// configuration entry. No supplied state is injected.
func TestAssurance_ConfigIndexBasis(t *testing.T) {
	c := MakeCluster(3, t, nil)
	defer c.Close()

	leader := c.Leader() // fatals unless exactly one node is in Leader state
	leaderAddr := string(leader.localAddr)

	applied := leader.Apply([]byte("assurance-index-probe"), 5*time.Second)
	if err := applied.Error(); err != nil {
		t.Fatalf("apply failed: %v", err)
	}

	// The main thread's authoritative view of the configurations. This is the
	// path snapshot.go uses to obtain the committed configuration and its index.
	mainReq := &configurationsFuture{}
	mainReq.ShutdownCh = leader.shutdownCh
	mainReq.init()
	select {
	case leader.configurationsCh <- mainReq:
	case <-leader.shutdownCh:
		t.Fatalf("raft shut down before the configurations request was served")
	}
	if err := mainReq.Error(); err != nil {
		t.Fatalf("configurations future: %v", err)
	}

	public := leader.GetConfiguration()
	if err := public.Error(); err != nil {
		t.Fatalf("GetConfiguration: %v", err)
	}

	stats := leader.Stats()

	fmt.Printf("CA_EVENT {\"event\":\"config_index_observation\","+
		"\"leader_addr\":%q,"+
		"\"main_latest_index\":%d,"+
		"\"main_committed_index\":%d,"+
		"\"main_latest_servers\":%d,"+
		"\"public_index\":%d,"+
		"\"public_servers\":%d,"+
		"\"stats_latest_configuration_index\":%q,"+
		"\"stats_latest_configuration\":%q,"+
		"\"applied_index\":%q,"+
		"\"commit_index\":%q,\"term\":%q}\n",
		leaderAddr,
		mainReq.configurations.latestIndex,
		mainReq.configurations.committedIndex,
		len(mainReq.configurations.latest.Servers),
		public.Index(),
		len(public.Configuration().Servers),
		stats["latest_configuration_index"],
		stats["latest_configuration"],
		stats["applied_index"],
		stats["commit_index"],
		stats["term"],
	)
}

package raft

import (
	"fmt"
	"io"
	"sync"
	"testing"
	"time"
)

// stallReader signals when its first Read call begins and then blocks until
// released. A Read that blocks for a long time is what a caller-supplied
// backup stream can do to the handler that consumes it.
type stallReader struct {
	started chan struct{}
	release chan struct{}
	once    sync.Once
}

func (s *stallReader) Read(p []byte) (int, error) {
	s.once.Do(func() { close(s.started) })
	<-s.release
	return 0, io.ErrUnexpectedEOF
}

// TestAssurance_QueuedDutyAtShutdown observes whether a duty that the public
// API already accepted (a Barrier future handed to the caller) still has a
// completion path once the node loses authority by Shutdown rather than by
// stepping down.
//
// Initialization: MakeCluster(3, conf) with conf.BatchApplyCh = true (a
// documented public option that buffers applyCh to MaxAppendEntries) bootstraps
// a real three-node cluster and elects a leader. The main loop is then occupied
// through the public Restore API with a caller-supplied reader that stalls on
// its first Read, so the loop is provably inside a handler and cannot select on
// applyCh again. A Barrier future is then enqueued by the ordinary public path.
func TestAssurance_QueuedDutyAtShutdown(t *testing.T) {
	conf := inmemConfig(t)
	conf.BatchApplyCh = true
	c := MakeCluster(3, t, conf)
	defer c.Close()

	leader := c.Leader()
	leaderAddr := string(leader.localAddr)

	// Control: the same public call completes while a producer is available.
	controlErr := ""
	if err := leader.Barrier(0).Error(); err != nil {
		controlErr = err.Error()
	}

	// Occupy the main loop with the public Restore path and a reader that
	// stalls. The reader's first Read is the handshake.
	reader := &stallReader{started: make(chan struct{}), release: make(chan struct{})}
	restoreErr := make(chan error, 1)
	go func() {
		restoreErr <- leader.Restore(&SnapshotMeta{Version: 1, ID: "assurance-stall", Index: 1, Term: 1, Size: 1}, reader, 0)
	}()

	handshake := "inside_restore_read"
	select {
	case <-reader.started:
	case <-time.After(5 * time.Second):
		handshake = "timeout"
	}

	// Accept a duty through the ordinary public path: the send into the
	// buffered apply channel succeeds and the caller holds the future.
	accepted := make(chan Future, 1)
	go func() { accepted <- leader.Barrier(0) }()
	var duty Future
	dutyAccepted := true
	select {
	case duty = <-accepted:
	case <-time.After(5 * time.Second):
		dutyAccepted = false
	}
	stateAtAccept := leader.State().String()

	// Lose authority by shutdown while the duty sits in the buffer.
	leader.Shutdown()

	waited := 3 * time.Second
	result := "not_attempted"
	waitedMs := int64(0)
	if dutyAccepted {
		waitStart := time.Now()
		done := make(chan error, 1)
		go func() { done <- duty.Error() }()
		result = "no_completion"
		select {
		case err := <-done:
			result = fmt.Sprintf("completed:%v", err)
		case <-time.After(waited):
		}
		waitedMs = time.Since(waitStart).Milliseconds()
	}

	queued := len(leader.applyCh)
	capacity := cap(leader.applyCh)
	stateAfter := leader.State().String()

	// Release the stalled reader so the occupied handler can return and the
	// node can finish shutting down.
	close(reader.release)
	restoreResult := ""
	select {
	case err := <-restoreErr:
		if err != nil {
			restoreResult = err.Error()
		}
	case <-time.After(3 * time.Second):
		restoreResult = "restore still blocked"
	}

	fmt.Printf("CA_EVENT {\"event\":\"queued_duty_at_shutdown\",\"leader_addr\":%q,"+
		"\"control_barrier_err\":%q,\"freeze_handshake\":%q,\"state_at_accept\":%q,"+
		"\"state_after_shutdown\":%q,\"duty_accepted\":%t,\"queued_in_apply_ch\":%d,"+
		"\"apply_ch_capacity\":%d,\"waited_ms\":%d,\"result\":%q,\"restore_after_release\":%q}\n",
		leaderAddr, controlErr, handshake, stateAtAccept, stateAfter,
		dutyAccepted, queued, capacity, waitedMs, result, restoreResult)
}

package raft

import (
	"fmt"
	"testing"
	"time"
)

// TestAssurance_TransferToNonVoter asks what a caller actually receives when it
// names a server that holds no vote as the target of an explicit leadership
// transfer.
//
// Initialization: MakeCluster(4) bootstraps a real four-voter cluster and
// elects a leader. One follower is then demoted to a non-voter through the
// public DemoteVoter API (a committed configuration change), so the named
// target is a real, connected, log-receiving member of the configuration that
// the leader itself replicates to, but holds no vote.
func TestAssurance_TransferToNonVoter(t *testing.T) {
	c := MakeCluster(4, t, nil)
	defer c.Close()

	leader := c.Leader()
	leaderAddr := string(leader.localAddr)

	var followers []*Raft
	limit := time.Now().Add(c.longstopTimeout)
	for time.Now().Before(limit) && len(followers) == 0 {
		c.WaitEvent(nil, c.conf.CommitTimeout)
		followers = c.GetInState(Follower)
	}
	if len(followers) == 0 {
		t.Fatalf("no follower available as a transfer target")
	}
	target := followers[0]
	targetAddr := string(target.localAddr)

	// Demote the target through the public API and wait for that configuration
	// entry to be applied.
	demoteErr := ""
	if err := leader.DemoteVoter(target.localID, 0, 5*time.Second).Error(); err != nil {
		demoteErr = err.Error()
	}

	suffrage := "unknown"
	for _, s := range leader.getLatestConfiguration().Servers {
		if s.ID == target.localID {
			suffrage = s.Suffrage.String()
		}
	}

	termBefore := uint64(0)
	for _, r := range c.rafts {
		if term := r.getCurrentTerm(); term > termBefore {
			termBefore = term
		}
	}

	// Ask for the transfer to the named, vote-less target.
	transferErr := ""
	if err := leader.LeadershipTransferToServer(target.localID, target.localAddr).Error(); err != nil {
		transferErr = err.Error()
	}

	// Watch who actually leads for a bounded interval, and whether the named
	// target ever reaches Leader.
	deadline := time.Now().Add(3 * time.Second)
	targetEverLeader := false
	originalLeaderLedAgain := false
	seenLeaders := map[string]bool{}
	for time.Now().Before(deadline) {
		for _, r := range c.rafts {
			if r.getState() != Leader {
				continue
			}
			a := string(r.localAddr)
			seenLeaders[a] = true
			if a == targetAddr {
				targetEverLeader = true
			}
			if a == leaderAddr {
				originalLeaderLedAgain = true
			}
		}
		time.Sleep(20 * time.Millisecond)
	}

	termAfter := uint64(0)
	for _, r := range c.rafts {
		if term := r.getCurrentTerm(); term > termAfter {
			termAfter = term
		}
	}

	leaders := ""
	for a := range seenLeaders {
		if leaders != "" {
			leaders += ","
		}
		leaders += a
	}
	leaderState := leader.State().String()
	targetState := target.State().String()

	fmt.Printf("CA_EVENT {\"event\":\"transfer_to_nonvoter\",\"leader_addr\":%q,\"target_addr\":%q,"+
		"\"target_suffrage\":%q,\"demote_err\":%q,\"transfer_err\":%q,"+
		"\"target_ever_leader\":%t,\"original_leader_led_again\":%t,\"leaders_seen\":%q,"+
		"\"leader_state_at_end\":%q,\"target_state_at_end\":%q,"+
		"\"term_before\":%d,\"term_after\":%d}\n",
		leaderAddr, targetAddr, suffrage, demoteErr, transferErr,
		targetEverLeader, originalLeaderLedAgain, leaders,
		leaderState, targetState, termBefore, termAfter)
}

