// GetConfiguration returns the latest configuration. This may not yet be
// committed. The main loop can access this directly.
func (r *Raft) GetConfiguration() ConfigurationFuture {
	configReq := &configurationsFuture{}
	configReq.init()
	configReq.configurations = configurations{latest: r.getLatestConfiguration()}
	configReq.respond(nil)
	return configReq
}

future := r.GetConfiguration()
if err := future.Error(); err != nil {
	r.logger.Warn("could not get configuration for stats", "error", err)
} else {
	configuration := future.Configuration()
	s["latest_configuration_index"] = toString(future.Index())
	s["latest_configuration"] = fmt.Sprintf("%+v", configuration.Servers)

// configurationsFuture is used to retrieve the current configurations. This is
// used to allow safe access to this information outside of the main thread.
type configurationsFuture struct {
	deferError
	configurations configurations
}

// Configuration returns the latest configuration in use by Raft.
func (c *configurationsFuture) Configuration() Configuration {
	return c.configurations.latest
}

// Index returns the index of the latest configuration in use by Raft.
func (c *configurationsFuture) Index() uint64 {
	return c.configurations.latestIndex
}

// setLatestConfiguration stores the latest configuration and updates a copy of it.
func (r *Raft) setLatestConfiguration(c Configuration, i uint64) {
	r.configurations.latest = c
	r.configurations.latestIndex = i
	r.latestConfiguration.Store(c.Clone())
}

// setCommittedConfiguration stores the committed configuration.
func (r *Raft) setCommittedConfiguration(c Configuration, i uint64) {
	r.configurations.committed = c
	r.configurations.committedIndex = i
}

// getLatestConfiguration reads the configuration from a copy of the main
// configuration, which means it can be accessed independently from the main
// loop.
func (r *Raft) getLatestConfiguration() Configuration {
	// this switch catches the case where this is called without having set
	// a configuration previously.
	switch c := r.latestConfiguration.Load().(type) {
	case Configuration:
		return c
	default:
		return Configuration{}
	}

func nextConfiguration(current Configuration, currentIndex uint64, change configurationChangeRequest) (Configuration, error) {
	if change.prevIndex > 0 && change.prevIndex != currentIndex {
		return Configuration{}, fmt.Errorf("configuration changed since %v (latest is %v)", change.prevIndex, currentIndex)
	}

// AddVoter will add the given server to the cluster as a staging server. If the
// server is already in the cluster as a voter, this updates the server's address.
// This must be run on the leader or it will fail. The leader will promote the
// staging server to a voter once that server is ready. If nonzero, prevIndex is
// the index of the only configuration upon which this change may be applied; if
// another configuration entry has been added in the meantime, this request will
// fail. If nonzero, timeout is how long this server should wait before the
// configuration change log entry is appended.
func (r *Raft) AddVoter(id ServerID, address ServerAddress, prevIndex uint64, timeout time.Duration) IndexFuture {
	if r.protocolVersion < 2 {
		return errorFuture{ErrUnsupportedProtocol}
	}

	return r.requestConfigChange(configurationChangeRequest{
		command:       AddVoter,
		serverID:      id,
		serverAddress: address,
		prevIndex:     prevIndex,
	}, timeout)
}

// Shutdown is used to stop the Raft background routines.
// This is not a graceful operation. Provides a future that
// can be used to block until all background routines have exited.
func (r *Raft) Shutdown() Future {
	r.shutdownLock.Lock()
	defer r.shutdownLock.Unlock()

	if !r.shutdown {
		close(r.shutdownCh)
		r.shutdown = true
		r.setState(Shutdown)
		return &shutdownFuture{r}
	}

	// avoid closing transport twice
	return &shutdownFuture{nil}
}

func (r *Raft) ApplyLog(log Log, timeout time.Duration) ApplyFuture {
	metrics.IncrCounter([]string{"raft", "apply"}, 1)

	var timer <-chan time.Time
	if timeout > 0 {
		timer = time.After(timeout)
	}

	// Create a log future, no index or term yet
	logFuture := &logFuture{
		log: Log{
			Type:       LogCommand,
			Data:       log.Data,
			Extensions: log.Extensions,
		},
	}
	logFuture.init()

	select {
	case <-timer:
		return errorFuture{ErrEnqueueTimeout}
	case <-r.shutdownCh:
		return errorFuture{ErrRaftShutdown}
	case r.applyCh <- logFuture:
		return logFuture
	}
}

// Barrier is used to issue a command that blocks until all preceding
// operations have been applied to the FSM. It can be used to ensure the
// FSM reflects all queued writes. An optional timeout can be provided to
// limit the amount of time we wait for the command to be started. This
// must be run on the leader, or it will fail.
func (r *Raft) Barrier(timeout time.Duration) Future {
	metrics.IncrCounter([]string{"raft", "barrier"}, 1)
	var timer <-chan time.Time
	if timeout > 0 {
		timer = time.After(timeout)
	}

	// Create a log future, no index or term yet
	logFuture := &logFuture{log: Log{Type: LogBarrier}}
	logFuture.init()

	select {
	case <-timer:
		return errorFuture{ErrEnqueueTimeout}
	case <-r.shutdownCh:
		return errorFuture{ErrRaftShutdown}
	case r.applyCh <- logFuture:
		return logFuture
	}
}

func TestRaft_AfterShutdown(t *testing.T) {
	c := MakeCluster(1, t, nil)
	c.Close()
	raft := c.rafts[0]

	// Everything should fail now
	if f := raft.Apply(nil, 0); f.Error() != ErrRaftShutdown {
		t.Fatalf("should be shutdown: %v", f.Error())
	}

	// TODO (slackpad) - Barrier, VerifyLeader, and GetConfiguration can get
	// stuck if the buffered channel consumes the future but things are shut
	// down so they never get processed.
	if f := raft.AddVoter(ServerID("id"), ServerAddress("addr"), 0, 0); f.Error() != ErrRaftShutdown {
		t.Fatalf("should be shutdown: %v", f.Error())
	}

// BatchApplyCh indicates whether we should buffer applyCh
// to size MaxAppendEntries. This enables batch log commitment,
// but breaks the timeout guarantee on Apply. Specifically,
// a log can be added to the applyCh buffer but not actually be
// processed until after the specified timeout.
BatchApplyCh bool

// deferError can be embedded to allow a future
// to provide an error in the future.
type deferError struct {
	err        error
	errCh      chan error
	responded  bool
	ShutdownCh chan struct{}
}

func (d *deferError) init() {
	d.errCh = make(chan error, 1)
}

func (d *deferError) Error() error {
	if d.err != nil {
		// Note that when we've received a nil error, this
		// won't trigger, but the channel is closed after
		// send so we'll still return nil below.
		return d.err
	}
	if d.errCh == nil {
		panic("waiting for response on nil channel")
	}
	select {
	case d.err = <-d.errCh:
	case <-d.ShutdownCh:
		d.err = ErrRaftShutdown
	}
	return d.err
}

func (d *deferError) respond(err error) {
	if d.errCh == nil {
		return
	}
	if d.responded {
		return
	}
	d.errCh <- err
	close(d.errCh)
	d.responded = true
}

// Restore the snapshot into the FSM. If this fails we are in a
// bad state so we panic to take ourselves out.
fsm := &restoreFuture{ID: sink.ID()}
fsm.ShutdownCh = r.shutdownCh
fsm.init()
select {

defer func() {
	close(stopCh)

	// Since we were the leader previously, we update our
	// last contact time when we step down, so that we are not
	// reporting a last contact time from before we were the
	// leader. Otherwise, to a client it would seem our data
	// is extremely stale.
	r.setLastContact()

	// Stop replication
	for _, p := range r.leaderState.replState {
		close(p.stopCh)
	}

	// Respond to all inflight operations
	for e := r.leaderState.inflight.Front(); e != nil; e = e.Next() {
		e.Value.(*logFuture).respond(ErrLeadershipLost)
	}

	// Respond to any pending verify requests
	for future := range r.leaderState.notify {
		future.respond(ErrLeadershipLost)
	}

	// Clear all the state
	r.leaderState.commitCh = nil
	r.leaderState.commitment = nil
	r.leaderState.inflight = nil
	r.leaderState.replState = nil
	r.leaderState.notify = nil
	r.leaderState.stepDown = nil

	// If we are stepping down for some reason, no known leader.
	// We may have stepped down due to an RPC call, which would
	// provide the leader, so we cannot always blank this out.
	r.leaderLock.Lock()
	if r.leaderAddr == r.localAddr && r.leaderID == r.localID {
		r.leaderAddr = ""
		r.leaderID = ""
	}
	r.leaderLock.Unlock()

	// Notify that we are not the leader
	overrideNotifyBool(r.leaderCh, false)

	// Push to the notify channel if given
	if notify != nil {
		select {
		case notify <- false:
		case <-r.shutdownCh:
			// On shutdown, make a best effort but do not block
			select {
			case notify <- false:
			default:
			}
		}
	}
}()

func (r *Raft) timeoutNow(rpc RPC, req *TimeoutNowRequest) {
	r.setLeader("", "")
	r.setState(Candidate)
	r.candidateFromLeadershipTransfer.Store(true)
	rpc.Respond(&TimeoutNowResponse{}, nil)
}

// check if pre-vote is active and that this is not a leader transfer.
// Leader transfer do not perform prevote by design
if !r.preVoteDisabled && !r.candidateFromLeadershipTransfer.Load() {
	prevoteCh = r.preElectSelf()
} else {
	voteCh = r.electSelf()
}

func (r *Raft) electSelf() <-chan *voteResult {
	// Create a response channel
	respCh := make(chan *voteResult, len(r.configurations.latest.Servers))

	// Increment the term
	newTerm := r.getCurrentTerm() + 1

	r.setCurrentTerm(newTerm)
	// Construct the request
	lastIdx, lastTerm := r.getLastEntry()
	req := &RequestVoteRequest{
		RPCHeader: r.getRPCHeader(),
		Term:      newTerm,
		// this is needed for retro compatibility, before RPCHeader.Addr was added
		Candidate:          r.trans.EncodePeer(r.localID, r.localAddr),
		LastLogIndex:       lastIdx,
		LastLogTerm:        lastTerm,
		LeadershipTransfer: r.candidateFromLeadershipTransfer.Load(),
	}

	// Construct a function to ask for a vote
	askPeer := func(peer Server) {
		r.goFunc(func() {
			defer metrics.MeasureSince([]string{"raft", "candidate", "electSelf"}, time.Now())
			resp := &voteResult{voterID: peer.ID}
			err := r.trans.RequestVote(peer.ID, peer.Address, req, &resp.RequestVoteResponse)
			if err != nil {
				r.logger.Error("failed to make requestVote RPC",
					"target", peer,
					"error", err,
					"term", req.Term)
				resp.Term = req.Term
				resp.Granted = false
			}
			respCh <- resp
		})
	}

	// For each peer, request a vote
	for _, server := range r.configurations.latest.Servers {
		if server.Suffrage == Voter {
			if server.ID == r.localID {
				r.logger.Debug("voting for self", "term", req.Term, "id", r.localID)

				// Persist a vote for ourselves
				if err := r.persistVote(req.Term, req.RPCHeader.Addr); err != nil {
					r.logger.Error("failed to persist vote", "error", err)
					return nil

				}
				// Include our own vote
				respCh <- &voteResult{
					RequestVoteResponse: RequestVoteResponse{
						RPCHeader: r.getRPCHeader(),
						Term:      req.Term,
						Granted:   true,
					},
					voterID: r.localID,
				}
			} else {
				r.logger.Debug("asking for vote", "term", req.Term, "from", server.ID, "address", server.Address)
				askPeer(server)
			}
		}
	}

	return respCh
}

func (r *Raft) pickServer() *Server {
	var pick *Server
	var current uint64
	for _, server := range r.configurations.latest.Servers {
		if server.ID == r.localID || server.Suffrage != Voter {
			continue
		}
		state, ok := r.leaderState.replState[server.ID]
		if !ok {
			continue
		}
		nextIdx := atomic.LoadUint64(&state.nextIndex)
		if nextIdx > current {
			current = nextIdx
			tmp := server
			pick = &tmp
		}
	}
	return pick
}

// Ignore an older term
if req.Term < r.getCurrentTerm() {
	return
}

// Increase the term if we see a newer one
if req.Term > r.getCurrentTerm() {
	// Ensure transition to follower
	r.logger.Debug("lost leadership because received a requestVote with a newer term")
	r.setState(Follower)
	r.setCurrentTerm(req.Term)

	resp.Term = req.Term
}

// if we get a request for vote from a nonVoter  and the request term is higher,
// step down and update term, but reject the vote request
// This could happen when a node, previously voter, is converted to non-voter
// The reason we need to step in is to permit to the cluster to make progress in such a scenario
// More details about that in https://github.com/hashicorp/raft/pull/526
if len(req.ID) > 0 {
	candidateID := ServerID(req.ID)
	if len(r.configurations.latest.Servers) > 0 && !hasVote(r.configurations.latest, candidateID) {
		r.logger.Warn("rejecting vote request since node is not a voter", "from", candidate)
		return
	}
}

func (r *Raft) LeadershipTransferToServer(id ServerID, address ServerAddress) Future {
	if r.protocolVersion < 3 {
		return errorFuture{ErrUnsupportedProtocol}
	}

	return r.initiateLeadershipTransfer(&id, &address)
}

} else {
	metrics.IncrCounter([]string{"raft", "transition", "heartbeat_timeout"}, 1)
	if hasVote(r.configurations.latest, r.localID) {
		r.logger.Warn("heartbeat timeout reached, starting election", "last-leader-addr", lastLeaderAddr, "last-leader-id", lastLeaderID)
		r.setState(Candidate)
		return
	} else if !didWarn {
		r.logger.Warn("heartbeat timeout reached, not part of a stable configuration or a non-voter, not triggering a leader election")
		didWarn = true
	}
}

case future := <-r.leadershipTransferCh:
	r.mainThreadSaturation.working()
	if r.getLeadershipTransferInProgress() {
		r.logger.Debug(ErrLeadershipTransferInProgress.Error())
		future.respond(ErrLeadershipTransferInProgress)
		continue
	}

	r.logger.Debug("starting leadership transfer", "id", future.ID, "address", future.Address)

	// When we are leaving leaderLoop, we are no longer
	// leader, so we should stop transferring.
	leftLeaderLoop := make(chan struct{})
	defer func() { close(leftLeaderLoop) }()

	stopCh := make(chan struct{})
	doneCh := make(chan error, 1)

	// This is intentionally being setup outside of the
	// leadershipTransfer function. Because the TimeoutNow
	// call is blocking and there is no way to abort that
	// in case eg the timer expires.
	// The leadershipTransfer function is controlled with
	// the stopCh and doneCh.
	// No matter how this exits, have this function set
	// leadership transfer to false before we return
	//
	// Note that this leaves a window where callers of
	// LeadershipTransfer() and LeadershipTransferToServer()
	// may start executing after they get their future but before
	// this routine has set leadershipTransferInProgress back to false.
	// It may be safe to modify things such that setLeadershipTransferInProgress
	// is set to false before calling future.Respond, but that still needs
	// to be tested and this situation mirrors what callers already had to deal with.
	go func() {
		defer r.setLeadershipTransferInProgress(false)
		select {
		case <-time.After(r.config().ElectionTimeout):
			close(stopCh)
			err := fmt.Errorf("leadership transfer timeout")
			r.logger.Debug(err.Error())
			future.respond(err)
			<-doneCh
		case <-leftLeaderLoop:
			close(stopCh)
			err := fmt.Errorf("lost leadership during transfer (expected)")
			r.logger.Debug(err.Error())
			future.respond(nil)
			<-doneCh
		case err := <-doneCh:
			if err != nil {
				r.logger.Debug(err.Error())
				future.respond(err)
			} else {
				// Wait for up to ElectionTimeout before flagging the
				// leadership transfer as done and unblocking applies in
				// the leaderLoop.
				select {
				case <-time.After(r.config().ElectionTimeout):
					err := fmt.Errorf("leadership transfer timeout")
					r.logger.Debug(err.Error())
					future.respond(err)
				case <-leftLeaderLoop:
					r.logger.Debug("lost leadership during transfer (expected)")
					future.respond(nil)
				}
			}
		}
	}()

switch change.command {
case AddVoter:
	newServer := Server{
		Suffrage: Voter,
		ID:       change.serverID,
		Address:  change.serverAddress,
	}
	found := false
	for i, server := range configuration.Servers {
		if server.ID == change.serverID {
			if server.Suffrage == Voter {
				configuration.Servers[i].Address = change.serverAddress
			} else {
				configuration.Servers[i] = newServer
			}
			found = true
			break
		}
	}
	if !found {
		configuration.Servers = append(configuration.Servers, newServer)
	}

type ConfigurationChangeCommand uint8

const (
	// AddVoter adds a server with Suffrage of Voter.
	AddVoter ConfigurationChangeCommand = iota
	// AddNonvoter makes a server Nonvoter unless its Staging or Voter.
	AddNonvoter
	// DemoteVoter makes a server Nonvoter unless its absent.
	DemoteVoter
	// RemoveServer removes a server entirely from the cluster membership.
	RemoveServer
	// Promote changes a server from Staging to Voter. The command will be a
	// no-op if the server is not Staging.
	// Deprecated: use AddVoter instead.
	Promote
	// AddStaging makes a server a Voter.
	// Deprecated: AddStaging was actually AddVoter. Use AddVoter instead.
	AddStaging = 0 // explicit 0 to preserve the old value.
)

case Promote:
	for i, server := range configuration.Servers {
		if server.ID == change.serverID && server.Suffrage == Staging {
			configuration.Servers[i].Suffrage = Voter
			break
		}
	}

